def polynomial_to_string(n: int, coeffs: list[int]) -> str:
    """
    Converts a list of polynomial coefficients into a formatted string representation.

    Args:
        n (int): The highest degree of the polynomial.
        coeffs (List[int]): A list of coefficients, starting with the coefficient of the highest degree term.

    Returns:
        str: The string representation of the polynomial.

    Raises:
        ValueError: If n is negative or the length of coeffs does not match n+1.
        TypeError: If coeffs is not a list of integers or n is not an integer.
    """
    # Basic input validation
    if not isinstance(n, int):
        raise TypeError("n must be an integer")
    if n < 0:
        raise ValueError("n must be non‑negative")
    if not isinstance(coeffs, list):
        raise TypeError("coeffs must be a list")
    if len(coeffs) != n + 1:
        raise ValueError(f"coeffs length must be {n + 1} for degree {n}")
    for c in coeffs:
        if not isinstance(c, int):
            raise TypeError("All coefficients must be integers")

    terms = []
    first_term = True

    for idx, coeff in enumerate(coeffs):
        degree = n - idx
        if coeff == 0:
            continue

        # Determine sign
        if first_term:
            sign = "-" if coeff < 0 else ""
        else:
            sign = "-" if coeff < 0 else "+"

        abs_coeff = abs(coeff)

        # Determine coefficient part
        if abs_coeff == 1 and degree != 0:
            coeff_part = ""
        else:
            coeff_part = str(abs_coeff)

        # Determine variable part
        if degree > 1:
            var_part = f"x^{degree}"
        elif degree == 1:
            var_part = "x"
        else:
            var_part = ""

        term = f"{sign}{coeff_part}{var_part}"
        terms.append(term)
        first_term = False

    if not terms:
        return "0"

    return "".join(terms)

def decode(encoded: str, original: str, message: str) -> str:
    """
    Decodes an encrypted message using a cipher derived from a known encoded-original pair.

    The function builds a mapping from encoded letters to their original letters and uses this
    mapping to decode a given encrypted message. If a contradiction is found during mapping
    construction, or not all letters are represented in the mapping, the function returns "Failed".

    Args:
    encoded (str): A string representing the encoded information.
    original (str): A string representing the original information corresponding to the encoded string.
    message (str): A string representing the encrypted message to be decoded.

    Returns:
    str: The decoded message if successful, or "Failed" if the decoding is not possible.
    """
    # Basic type checks
    if not isinstance(encoded, str) or not isinstance(original, str) or not isinstance(message, str):
        return "Failed"

    # Length must match
    if len(encoded) != len(original):
        return "Failed"

    # Build mapping and reverse mapping
    mapping = {}
    rev_mapping = {}
    for e_char, o_char in zip(encoded, original):
        # Ensure characters are uppercase letters
        if not ('A' <= e_char <= 'Z') or not ('A' <= o_char <= 'Z'):
            return "Failed"
        # Check consistency
        if e_char in mapping:
            if mapping[e_char] != o_char:
                return "Failed"
        else:
            mapping[e_char] = o_char
        if o_char in rev_mapping:
            if rev_mapping[o_char] != e_char:
                return "Failed"
        else:
            rev_mapping[o_char] = e_char

    # Ensure all 26 letters are represented in both directions
    alphabet = set('ABCDEFGHIJKLMNOPQRSTUVWXYZ')
    if set(mapping.keys()) != alphabet or set(mapping.values()) != alphabet:
        return "Failed"

    # Decode the message
    decoded_chars = []
    for ch in message:
        if ch not in mapping:
            return "Failed"
        decoded_chars.append(mapping[ch])

    return ''.join(decoded_chars)

def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    """
    Perform string transformation from A to B using a set of transformation rules.
    Uses BFS up to a maximum of 10 steps. Returns the minimum number of steps
    required to transform A into B, or "NO ANSWER!" if impossible.
    """
    try:
        # Basic input validation
        if not isinstance(A, str) or not isinstance(B, str) or not isinstance(rules, list):
            return "NO ANSWER!"
        for r in rules:
            if not isinstance(r, tuple) or len(r) != 2:
                return "NO ANSWER!"
            src, tgt = r
            if not isinstance(src, str) or not isinstance(tgt, str):
                return "NO ANSWER!"

        # Immediate success
        if A == B:
            return 0

        max_depth = 10
        queue = [(A, 0)]
        visited = {A}

        while queue:
            current, depth = queue.pop(0)
            if depth >= max_depth:
                continue

            for src, tgt in rules:
                start = 0
                while True:
                    idx = current.find(src, start)
                    if idx == -1:
                        break
                    new_str = current[:idx] + tgt + current[idx + len(src):]
                    if new_str == B:
                        return depth + 1
                    if new_str not in visited:
                        visited.add(new_str)
                        queue.append((new_str, depth + 1))
                    start = idx + 1

        return "NO ANSWER!"
    except Exception:
        return "NO ANSWER!"

def is_prime(num: int) -> bool:
    """
    Determine whether a given integer is a prime number.

    A prime number is a natural number greater than 1 that has no positive divisors other than 1 and itself. The function checks for primality by eliminating non-prime numbers using several tests. First, it handles edge cases for numbers less than or equal to 1, which are not prime, and small numbers (2 and 3) which are prime. It then checks for divisibility by 2 and 3. For larger numbers, it uses a 6k +/- 1 optimization to test for factors up to the square root of the number.

    Args:
    num (int): The integer to check for primality.

    Returns:
    bool: True if `num` is a prime number, False otherwise.
    """
    if not isinstance(num, int):
        raise TypeError("num must be an integer")
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

